"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Designed as a baseline for multi-session stories.
"""

from flask import Flask, request, jsonify, g
from datetime import datetime, timedelta, timezone
from functools import wraps
import base64
import hashlib
import hmac
import json
import os
from celery import Celery
from werkzeug.security import check_password_hash, generate_password_hash
from repositories import TaskRepository, UserRepository

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")
JWT_SECRET = os.environ.get("JWT_SECRET", "development-only-secret")
JWT_EXPIRATION_HOURS = 24
celery = Celery("task_notifications")
celery.config_from_object("celery_config")


@celery.task
def send_notification_email(user_email: str, task_title: str) -> None:
    """Send the completion notification from a Celery worker."""
    app.logger.info("Task '%s' completed; notifying %s", task_title, user_email)


def init_db():
    UserRepository(DATABASE).initialize()
    TaskRepository(DATABASE).initialize()


init_db()


def _encode_segment(value: dict) -> str:
    return base64.urlsafe_b64encode(json.dumps(value, separators=(",", ":")).encode()).rstrip(b"=").decode()


def _decode_segment(value: str) -> dict:
    return json.loads(base64.urlsafe_b64decode(value + "=" * (-len(value) % 4)))


def create_token(user_id: int) -> str:
    header = _encode_segment({"alg": "HS256", "typ": "JWT"})
    payload = _encode_segment({
        "sub": user_id,
        "exp": int((datetime.now(timezone.utc) + timedelta(hours=JWT_EXPIRATION_HOURS)).timestamp()),
    })
    signed = f"{header}.{payload}"
    signature = base64.urlsafe_b64encode(
        hmac.new(JWT_SECRET.encode(), signed.encode(), hashlib.sha256).digest()
    ).rstrip(b"=").decode()
    return f"{signed}.{signature}"


def verify_token(token: str) -> int | None:
    try:
        header, payload, signature = token.split(".")
        expected = base64.urlsafe_b64encode(
            hmac.new(JWT_SECRET.encode(), f"{header}.{payload}".encode(), hashlib.sha256).digest()
        ).rstrip(b"=").decode()
        claims = _decode_segment(payload)
        if not hmac.compare_digest(signature, expected) or claims["exp"] < datetime.now(timezone.utc).timestamp():
            return None
        return int(claims["sub"])
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        return None


def require_auth(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        scheme, _, token = authorization.partition(" ")
        user_id = verify_token(token) if scheme == "Bearer" and token else None
        if user_id is None:
            return jsonify({"error": "authentication required"}), 401
        g.user_id = user_id
        return view(*args, **kwargs)
    return wrapped


# ── Routes ─────────────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username, password = data.get("username"), data.get("password")
    if not isinstance(username, str) or not username.strip() or not isinstance(password, str) or not password:
        return jsonify({"error": "username and password are required"}), 400
    email = data.get("email", username)
    if not isinstance(email, str) or not email.strip():
        return jsonify({"error": "email must be a non-empty string"}), 400
    user = UserRepository(DATABASE).create_user(
        username.strip(), email.strip(), generate_password_hash(password)
    )
    if user is None:
        return jsonify({"error": "username already exists"}), 409
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username, password = data.get("username"), data.get("password")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"error": "invalid username or password"}), 401
    user = UserRepository(DATABASE).get_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid username or password"}), 401
    return jsonify({"token": create_token(user["id"])})

@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    return jsonify(TaskRepository(DATABASE).list_for_owner(g.user_id))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    title = title.strip()
    task = TaskRepository(DATABASE).create({
        "title": title,
        "status": "pending",
        "created_at": datetime.utcnow().isoformat(),
        "owner_id": g.user_id,
    })
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(task_id: int):
    task = TaskRepository(DATABASE).get_for_owner(task_id, g.user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if title is not None and (not isinstance(title, str) or not title.strip()):
        return jsonify({"error": "title must be a non-empty string"}), 400

    task_repository = TaskRepository(DATABASE)
    previous_task = task_repository.get_for_owner(task_id, g.user_id)
    if previous_task is None:
        return jsonify({"error": "task not found"}), 404

    updates = {}
    if title is not None:
        updates["title"] = title.strip()
    if data.get("status") is not None:
        updates["status"] = data["status"]
    task = task_repository.update_for_owner(task_id, g.user_id, updates)
    if previous_task["status"] != "completed" and task["status"] == "completed":
        user = UserRepository(DATABASE).get_by_id(g.user_id)
        send_notification_email.delay(user["email"], task["title"])
    return jsonify(task)


if __name__ == "__main__":
    app.run(debug=True)

from abc import ABC
import sqlite3
from typing import Any


class BaseRepository(ABC):
    """Shared SQLite CRUD helpers for a single table."""

    table_name: str

    def __init__(self, database: str):
        self.database = database

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.database)
        connection.row_factory = sqlite3.Row
        return connection

    def create(self, values: dict[str, Any]) -> dict:
        columns = ", ".join(values)
        placeholders = ", ".join("?" for _ in values)
        with self._connect() as connection:
            cursor = connection.execute(
                f"INSERT INTO {self.table_name} ({columns}) VALUES ({placeholders})",
                tuple(values.values()),
            )
            row = connection.execute(
                f"SELECT * FROM {self.table_name} WHERE id = ?", (cursor.lastrowid,)
            ).fetchone()
            return dict(row)

    def get_by_id(self, record_id: int) -> dict | None:
        with self._connect() as connection:
            row = connection.execute(
                f"SELECT * FROM {self.table_name} WHERE id = ?", (record_id,)
            ).fetchone()
            return dict(row) if row else None

    def get_all(self, where: str = "", params: tuple = (), order_by: str = "") -> list[dict]:
        query = f"SELECT * FROM {self.table_name}"
        if where:
            query += f" WHERE {where}"
        if order_by:
            query += f" ORDER BY {order_by}"
        with self._connect() as connection:
            return [dict(row) for row in connection.execute(query, params).fetchall()]

    def update(self, record_id: int, values: dict[str, Any], where: str = "", params: tuple = ()) -> dict | None:
        if not values:
            return self.get_by_id(record_id)
        assignments = ", ".join(f"{column} = ?" for column in values)
        condition = "id = ?"
        if where:
            condition += f" AND {where}"
        with self._connect() as connection:
            connection.execute(
                f"UPDATE {self.table_name} SET {assignments} WHERE {condition}",
                (*values.values(), record_id, *params),
            )
        if where:
            records = self.get_all(f"id = ? AND {where}", (record_id, *params))
            return records[0] if records else None
        return self.get_by_id(record_id)

    def delete(self, record_id: int) -> bool:
        with self._connect() as connection:
            cursor = connection.execute(f"DELETE FROM {self.table_name} WHERE id = ?", (record_id,))
            return cursor.rowcount > 0


class TaskRepository(BaseRepository):
    table_name = "tasks"

    def initialize(self) -> None:
        with self._connect() as connection:
            connection.execute(
                "CREATE TABLE IF NOT EXISTS tasks ("
                "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
                "  title TEXT NOT NULL,"
                "  status TEXT NOT NULL DEFAULT 'pending',"
                "  created_at TEXT NOT NULL,"
                "  owner_id INTEGER REFERENCES users(id)"
                ")"
            )
            columns = {row["name"] for row in connection.execute("PRAGMA table_info(tasks)")}
            if "owner_id" not in columns:
                connection.execute("ALTER TABLE tasks ADD COLUMN owner_id INTEGER REFERENCES users(id)")

    def list_for_owner(self, owner_id: int) -> list[dict]:
        return self.get_all("owner_id = ?", (owner_id,), "created_at DESC")

    def get_for_owner(self, task_id: int, owner_id: int) -> dict | None:
        tasks = self.get_all("id = ? AND owner_id = ?", (task_id, owner_id))
        return tasks[0] if tasks else None

    def update_for_owner(self, task_id: int, owner_id: int, values: dict[str, Any]) -> dict | None:
        return self.update(task_id, values, "owner_id = ?", (owner_id,))


class UserRepository(BaseRepository):
    table_name = "users"

    def initialize(self) -> None:
        with self._connect() as connection:
            connection.execute(
                "CREATE TABLE IF NOT EXISTS users ("
                "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
                "  username TEXT NOT NULL UNIQUE,"
                "  email TEXT,"
                "  password_hash TEXT NOT NULL"
                ")"
            )
            columns = {row["name"] for row in connection.execute("PRAGMA table_info(users)")}
            if "email" not in columns:
                connection.execute("ALTER TABLE users ADD COLUMN email TEXT")
                connection.execute("UPDATE users SET email = username WHERE email IS NULL")

    def create_user(self, username: str, email: str, password_hash: str) -> dict | None:
        try:
            user = self.create({"username": username, "email": email, "password_hash": password_hash})
        except sqlite3.IntegrityError:
            return None
        return {"id": user["id"], "username": user["username"]}

    def get_by_username(self, username: str) -> dict | None:
        users = self.get_all("username = ?", (username,))
        return users[0] if users else None

